import sys
from collections import Counter

def main():
    sys.setrecursionlimit(300000)
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    K = int(next(it))
    total_nodes = N * K

    adj = [[] for _ in range(total_nodes + 1)]
    for _ in range(total_nodes - 1):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)

    ok = True

    def dfs(u, p):
        nonlocal ok
        if not ok:
            return 0

        child_vals = []
        for v in adj[u]:
            if v == p:
                continue
            res = dfs(v, u)
            if not ok:
                return 0
            if res < K:
                child_vals.append(res)

        if not child_vals:
            return 1

        cnt = Counter(child_vals)
        for x in list(cnt.keys()):
            if cnt[x] == 0:
                continue
            y = K - 1 - x
            if y == x:
                p_cnt = cnt[x] // 2
                cnt[x] -= p_cnt * 2
            elif y > x:
                if y in cnt:
                    p_cnt = min(cnt[x], cnt[y])
                    cnt[x] -= p_cnt
                    cnt[y] -= p_cnt

        rem = sum(cnt.values())
        if rem > 1:
            ok = False
            return 0
        elif rem == 1:
            val = next(x for x in cnt if cnt[x] > 0)
            return val + 1
        else:
            return 1

    final_res = dfs(1, 0)

    if ok and final_res == K:
        sys.stdout.write("Yes\n")
    else:
        sys.stdout.write("No\n")

if __name__ == "__main__":
    main()

import sys
sys.setrecursionlimit(100000)

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    N = int(data[0])
    S = data[1].strip()

    # Parse into ordered rooted forest.
    children = []   # children[i] = list of node ids
    def new_node():
        children.append([])
        return len(children) - 1

    roots = []
    stack = []
    for ch in S:
        if ch == '(':
            u = new_node()
            if stack:
                children[stack[-1]].append(u)
            else:
                roots.append(u)
            stack.append(u)
        else:
            stack.pop()

    # Canonical ids for shape and mirror-shape.
    # shape(node) = tuple of child shapes in order.
    # mirror(node) = tuple of child mirror-shapes in reverse order.
    shape_id = {}
    mirror_id = {}
    def get_shape(key):
        if key in shape_id:
            return shape_id[key]
        i = len(shape_id)
        shape_id[key] = i
        return i
    def get_mirror(key):
        if key in mirror_id:
            return mirror_id[key]
        i = len(mirror_id)
        mirror_id[key] = i
        return i

    n = len(children)
    shp = [0]*n
    mir = [0]*n
    # parent id < child id (ids assigned on '('), so decreasing id order works.
    for u in range(n-1, -1, -1):
        cs = children[u]
        skey = tuple(shp[v] for v in cs)
        mkey = tuple(mir[v] for v in reversed(cs))
        shp[u] = get_shape(skey)
        mir[u] = get_mirror(mkey)

    # Mirror-class: unordered pair {shp, mir}; symmetric iff shp == mir.
    class_id = {}
    def get_class(key):
        if key in class_id:
            return class_id[key]
        i = len(class_id)
        class_id[key] = i
        return i

    cls = [0]*n
    sym = [False]*n
    for u in range(n):
        a, b = shp[u], mir[u]
        sym[u] = (a == b)
        if a > b:
            a, b = b, a
        cls[u] = get_class((a, b))

    # factorials / inverse factorials
    fact = [1]*(N+2)
    for i in range(1, N+2):
        fact[i] = fact[i-1]*i % MOD
    invfact = [1]*(N+2)
    invfact[N+1] = pow(fact[N+1], MOD-2, MOD)
    for i in range(N+1, 0, -1):
        invfact[i-1] = invfact[i]*i % MOD

    def multinomial(total, counts):
        res = fact[total]
        for c in counts:
            res = res * invfact[c] % MOD
        return res

    def factor_for(kids):
        groups = {}
        for v in kids:
            groups.setdefault(cls[v], []).append(v)
        m = len(kids)
        res = multinomial(m, [len(g) for g in groups.values()])
        for g in groups.values():
            if not sym[g[0]]:
                res = res * pow(2, len(g), MOD) % MOD
        return res

    ans = 1
    ans = ans * factor_for(roots) % MOD
    for u in range(n):
        if children[u]:
            ans = ans * factor_for(children[u]) % MOD

    print(ans % MOD)

main()

from typing import List


class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # For each right endpoint b (the larger value of a pair), track the
        # largest partner a (best), the effective second largest (second),
        # and how many pairs achieve the maximum (cnt, for duplicates).
        best = [0] * (n + 1)
        second = [0] * (n + 1)
        cnt = [0] * (n + 1)

        for x, y in conflictingPairs:
            a, b = (x, y) if x < y else (y, x)
            if a > best[b]:
                second[b] = best[b]
                best[b] = a
                cnt[b] = 1
            elif a == best[b]:
                cnt[b] += 1
            elif a > second[b]:
                second[b] = a

        # If the maximum partner occurs in multiple pairs, removing one of
        # them leaves the constraint unchanged -> effective second = best.
        for b in range(1, n + 1):
            if cnt[b] > 1:
                second[b] = best[b]

        baseline = 0          # valid subarrays with all pairs present
        max_gain = 0          # best extra subarrays from removing one pair
        cur = 0               # current running max of best[1..r]
        rec = -1              # right endpoint that set the current record
        pm = 0                # max(second[rec], best values seen after rec)
        gains = {}            # gain per record position

        for r in range(1, n + 1):
            if best[r] > cur:
                # New record: constraint best[r] becomes the binding one.
                cur = best[r]
                rec = r
                pm = second[r]
                gains[rec] = 0
            else:
                if rec != -1 and best[r] > pm:
                    pm = best[r]
            baseline += r - cur
            if rec != -1:
                gains[rec] += cur - pm

        for g in gains.values():
            if g > max_gain:
                max_gain = g

        return baseline + max_gain

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # forced[j] = character forced at position j by some T-window, or None
        forced = [None] * L

        # Propagate T constraints
        for i, ch in enumerate(str1):
            if ch == 'T':
                for k in range(m):
                    j = i + k
                    c = str2[k]
                    if forced[j] is None:
                        forced[j] = c
                    elif forced[j] != c:
                        return ""

        # For each F-window starting at i, compute lastBreak[i]:
        # the last position p in [i, i+m-1] such that the window can be broken at p,
        # i.e. forced[p] is None or forced[p] != str2[p-i].
        # If no such position exists -> infeasible.
        lastBreak = [-1] * n  # only meaningful for F indices
        # bucket[j] = list of F-window start indices whose lastBreak == j
        bucket = [[] for _ in range(L)]

        for i, ch in enumerate(str1):
            if ch == 'F':
                lb = -1
                # scan window from right to left to find last breakable position
                for p in range(i + m - 1, i - 1, -1):
                    k = p - i
                    fp = forced[p]
                    if fp is None or fp != str2[k]:
                        lb = p
                        break
                if lb == -1:
                    return ""
                lastBreak[i] = lb
                bucket[lb].append(i)

        word = [None] * L

        # Active F-windows state:
        # A window i is "matching" while word[i..j] == str2[0..j-i] so far and not broken.
        # We maintain a deque of active matching windows covering the current position.
        # When we place c at j, windows with str2[j-i] != c become broken.
        from collections import deque

        active = deque()  # window starts i (F) that are unbroken and i <= j
        broken = [False] * n  # broken status per F window

        for j in range(L):
            # add newly starting F windows
            if j < n and str1[j] == 'F':
                active.append(j)
            # remove windows that ended before j
            while active and active[0] + m - 1 < j:
                active.popleft()

            if forced[j] is not None:
                c = forced[j]
                word[j] = c
                # update active windows
                new_active = deque()
                for i in active:
                    k = j - i
                    if str2[k] != c:
                        broken[i] = True
                    else:
                        # still matching; if window ends here -> infeasible
                        if i + m - 1 == j:
                            return ""
                        new_active.append(i)
                active = new_active
            else:
                # free position: determine forbidden chars from windows whose
                # lastBreak == j (must break now) and that are still unbroken/matching
                forbidden = set()
                if bucket[j]:
                    for i in bucket[j]:
                        if not broken[i]:
                            # window i must be broken at j: c != str2[j-i]
                            forbidden.add(str2[j - i])
                # choose smallest c not forbidden
                c = None
                for cand in range(26):
                    cc = chr(ord('a') + cand)
                    if cc not in forbidden:
                        c = cc
                        break
                if c is None:
                    return ""
                word[j] = c
                # update active windows
                new_active = deque()
                for i in active:
                    k = j - i
                    if str2[k] != c:
                        broken[i] = True
                    else:
                        if i + m - 1 == j:
                            # window completed as exact match -> this c invalid
                            # This can only happen if c was forced to match, but c is
                            # free here; however forbidden logic should have prevented
                            # it when lastBreak == j. If lastBreak > j it can't be that
                            # window ends at j (j is last position => lastBreak <= j).
                            # So this indicates infeasibility.
                            return ""
                        new_active.append(i)
                active = new_active

        # Final verification pass
        s = ''.join(word)
        for i, ch in enumerate(str1):
            sub = s[i:i + m]
            if ch == 'T':
                if sub != str2:
                    return ""
            else:
                if sub == str2:
                    return ""
        return s

import sys

def solve_one(n, A, B):
    p = [i for i in range(n) if A[i] == '1']
    q = [i for i in range(n) if B[i] == '1']
    m, r = len(p), len(q)
    if m < r:
        return -1
    if r == 1:
        return max(abs(p[0] - q[0]), abs(p[-1] - q[0]))

    # Greedy min-max monotone surjection f: group i -> target f[i]
    f = [0] * m
    j = 0
    for i in range(1, m):
        if j + 1 < r and (m - 1 - i) >= (r - 1 - (j + 1)):
            if abs(p[i] - q[j + 1]) <= abs(p[i] - q[j]):
                j += 1
        f[i] = j
    if f[m - 1] != r - 1:
        return -1

    delta = [q[f[i]] - p[i] for i in range(m)]
    for i in range(m - 1):
        if delta[i] < delta[i + 1]:
            return -1

    def plateau_mask(dl):
        mask = 0
        i = 0
        L = len(dl)
        while i < L - 1:
            if dl[i] == dl[i + 1]:
                mask |= 1 << (dl[i] & 1)
                while i < L - 1 and dl[i] == dl[i + 1]:
                    i += 1
            else:
                i += 1
        return mask

    def min_D(dl, mask):
        mx = max(abs(x) for x in dl)
        if mask == 3:
            return None
        if mask == 0:
            return mx
        need = 0 if mask == 1 else 1
        return mx if (mx & 1) == need else mx + 1

    mask = plateau_mask(delta)
    D = min_D(delta, mask)
    if D is not None:
        return D

    best = [None]

    def consider(nf):
        nd = [q[nf[i]] - p[i] for i in range(m)]
        for i in range(m - 1):
            if nd[i] < nd[i + 1]:
                return
        nmask = plateau_mask(nd)
        d = min_D(nd, nmask)
        if d is not None and (best[0] is None or d < best[0]):
            best[0] = d

    def assign_with_forced(a, t):
        # greedy assignment but with f[a] forced to t (a >= 1)
        nf = [0] * m
        jj = 0
        for i in range(1, m):
            if i == a:
                if t < jj or (m - 1 - i) < (r - 1 - t):
                    return None
                jj = t
            else:
                if jj + 1 < r and (m - 1 - i) >= (r - 1 - (jj + 1)):
                    if abs(p[i] - q[jj + 1]) <= abs(p[i] - q[jj]):
                        jj += 1
            nf[i] = jj
        if nf[m - 1] != r - 1:
            return None
        return nf

    # Mixed plateau parities: try local repairs per plateau run.
    i = 0
    while i < m - 1:
        if delta[i] == delta[i + 1]:
            s = i
            v = delta[i]
            while i < m - 1 and delta[i] == delta[i + 1]:
                i += 1
            e = i  # run is [s, e], value v
            # Option A (v < 0): bump f[e] up by one, re-greedy the suffix.
            if v < 0 and f[e] + 1 < r and (m - 1 - e) >= (r - 1 - (f[e] + 1)):
                nf = assign_with_forced(e, f[e] + 1)
                if nf is not None:
                    consider(nf)
            # Option B (v > 0): force f[s] down by one, re-greedy the rest.
            if v > 0 and s > 0 and f[s] - 1 >= 0:
                nf = assign_with_forced(s, f[s] - 1)
                if nf is not None:
                    consider(nf)
            # Option C (v >= 0): alternative tie-break, advance earlier.
            if v >= 0 and f[s] + 1 < r and (m - 1 - s) >= (r - 1 - (f[s] + 1)):
                nf = assign_with_forced(s, f[s] + 1) if s > 0 else None
                if nf is not None:
                    consider(nf)
        else:
            i += 1

    return best[0] if best[0] is not None else -1


def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    out = []
    idx = 1
    for _ in range(t):
        n = int(data[idx]); idx += 1
        A = data[idx].decode(); idx += 1
        B = data[idx].decode(); idx += 1
        out.append(str(solve_one(n, A, B)))
    sys.stdout.write('\n'.join(out) + '\n')

