            if end_idx != -1:
                ans[left_idx] = 1
                ans[mid_idx] = 1
                ans[end_idx] = 1
                print(3)
                print(' '.join(map(str, ans)))
                return

    # Prefix top-2 max-R structure over intervals sorted by L
    idx_by_L = sorted(range(M), key=lambda i: L[i])
    Ls = [L[i] for i in idx_by_L]
    pref_max1 = [-1] * M
    pref_max2 = [-1] * M
    for k in range(M):
        i = idx_by_L[k]
        if k == 0:
            pref_max1[k] = i
            pref_max2[k] = -1
        else:
            p1 = pref_max1[k-1]
            p2 = pref_max2[k-1]
            if p1 == -1 or R[i] >= R[p1]:
                pref_max1[k] = i
                pref_max2[k] = p1
            elif p2 == -1 or R[i] > R[p2]:
                pref_max1[k] = p1
                pref_max2[k] = i
            else:
                pref_max1[k] = p1
                pref_max2[k] = p2

    import bisect

    def query_maxR(x, ex1, ex2):
        # max R among indices with L <= x, excluding ex1 and ex2
        k = bisect.bisect_right(Ls, x) - 1
        if k < 0:
            return (-1, -1)
        c1 = pref_max1[k]
        if c1 != -1 and c1 != ex1 and c1 != ex2:
            return (R[c1], c1)
        c2 = pref_max2[k]
        if c2 != -1 and c2 != ex1 and c2 != ex2:
            return (R[c2], c2)
        # fallback: linear scan (rare)
        best = -1
        besti = -1
        for t in range(k + 1):
            i = idx_by_L[t]
            if i != ex1 and i != ex2 and R[i] > best:
                best = R[i]
                besti = i
        return (best, besti)

    # Type (iii): 1 complement C_b + 2 intervals covering [L_b, R_b]
    found3 = None
    for b in range(M):
        Lb, Rb = L[b], R[b]
        r1, a = query_maxR(Lb, b, -1)
