    # Type (ii): 2 complements + 1 interval containing I_b ∩ I_c
    byL = sorted(range(M), key=lambda i: (-L[i], R[i]))[:2]
    byR = sorted(range(M), key=lambda i: (R[i], -L[i]))[:2]
    for b in byL:
        for c in byR:
            if b == c:
                continue
            segL = L[b] if L[b] > L[c] else L[c]
            segR = R[b] if R[b] < R[c] else R[c]
            if segL > segR:
                continue
            r1, a = query_maxR(segL, b, c)
            if a != -1 and r1 >= segR:
                ans[b] = 2
                ans[c] = 2
                ans[a] = 1
                print(3)
                print(' '.join(map(str, ans)))
                return

    print(-1)

main()

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    p = int(data[idx]); idx += 1
    A = []
    for i in range(N):
        row = [int(x) % p for x in data[idx:idx+N]]
        idx += N
        A.append(row)

    # p = 2 special case: only filling is x=1, answer = B^2 mod 2
    if p == 2:
        B = [[1 if A[i][j] == 0 else A[i][j] for j in range(N)] for i in range(N)]
        C = [[0]*N for _ in range(N)]
        for i in range(N):
            Bi = B[i]
            Ci = C[i]
            for k in range(N):
                if Bi[k]:
                    Bk = B[k]
                    a = Bi[k]
                    for j in range(N):
                        Ci[j] = (Ci[j] + a * Bk[j]) & 1
        out = "\n".join(" ".join(map(str, row)) for row in C)
        sys.stdout.write(out + "\n")
        return

    # A' = A with zeros kept as 0 (already the case)
    Ap = A

    def matmul(X, Y):
        Z = [[0]*N for _ in range(N)]
        mod = p
        for i in range(N):
            Xi = X[i]
            Zi = Z[i]
            for k in range(N):
                a = Xi[k]
                if a:
                    Yk = Y[k]
                    for j in range(N):
                        Zi[j] = (Zi[j] + a * Yk[j]) % mod
        return Z

    def matpow(M, e):
        R = [[1 if i == j else 0 for j in range(N)] for i in range(N)]
        base = M
        while e > 0:
            if e & 1:
                R = matmul(R, base)
            e >>= 1
            if e:
                base = matmul(base, base)
        return R

    P = matpow(Ap, p)

    K = 0
    diag_zeros = []
    offdiag_zeros = []
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                K += 1
                if i == j:
                    diag_zeros.append(i)
                else:
                    offdiag_zeros.append((i, j))

    ans = P
    mod = p

    # Diagonal zero at (u,u): add A'E_u + E_u A'
    # (A'E_u) has column u = column u of A'; (E_u A') has row u = row u of A'
    for u in diag_zeros:
        # add column u of Ap into column u of ans
        for i in range(N):
            ans[i][u] = (ans[i][u] + Ap[i][u]) % mod
        # add row u of Ap into row u of ans
        rowu = Ap[u]
        ansu = ans[u]
        for j in range(N):
            ansu[j] = (ansu[j] + rowu[j]) % mod

    # Off-diagonal zeros contribute only when p == 3: add A'[v][u] at (u,v)
    if p == 3:
        for (u, v) in offdiag_zeros:
            ans[u][v] = (ans[u][v] + Ap[v][u]) % mod

    # Global factor (-1)^K
    if K % 2 == 1:
        for i in range(N):
            for j in range(N):
                if ans[i][j]:
                    ans[i][j] = mod - ans[i][j]

    out = "\n".join(" ".join(map(str, row)) for row in ans)
    sys.stdout.write(out + "\n")

solve()

from typing import List
from collections import defaultdict


class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        NEG_INF = float('-inf')

        size = 1
        while size < n:
            size <<= 1

        # Node: (total, best_prefix, best_suffix, best_subarray)
        tree = [(0, NEG_INF, NEG_INF, NEG_INF)] * (2 * size)

        def combine(a, b):
            total = a[0] + b[0]
            pref = a[1] if a[1] > a[0] + b[1] else a[0] + b[1]
            suff = b[2] if b[2] > b[0] + a[2] else b[0] + a[2]
            best = a[3] if a[3] > b[3] else b[3]
            cross = a[2] + b[1]
            if cross > best:
                best = cross
            return (total, pref, suff, best)

        for i, v in enumerate(nums):
            tree[size + i] = (v, v, v, v)
        for i in range(size - 1, 0, -1):
            tree[i] = combine(tree[2 * i], tree[2 * i + 1])

        IDENTITY = (0, NEG_INF, NEG_INF, NEG_INF)

        def query_node(l, r):
            """Return merged node over nums[l..r] inclusive (l <= r)."""
            l += size
            r += size
            left_res = IDENTITY
            right_res = IDENTITY
            while l <= r:
                if l & 1:
                    left_res = combine(left_res, tree[l])
                    l += 1
                if not (r & 1):
                    right_res = combine(tree[r], right_res)
                    r -= 1
                l >>= 1
                r >>= 1
            return combine(left_res, right_res)

        # Case 1: no deletion
        ans = query_node(0, n - 1)[3]

        # Group indices by value
        positions = defaultdict(list)
        for i, v in enumerate(nums):
            positions[v].append(i)

        # Case 2: delete all occurrences of x. The remaining gaps become
        # adjacent, so merge gap nodes in order and take the best field.
        for x, idxs in positions.items():
            if len(idxs) == n:
                continue  # deletion would empty the array
            merged = IDENTITY
            prev = -1
            for idx in idxs:
                if idx - 1 >= prev + 1:
                    merged = combine(merged, query_node(prev + 1, idx - 1))
                prev = idx
            if prev + 1 <= n - 1:
                merged = combine(merged, query_node(prev + 1, n - 1))
            if merged[3] > ans:
                ans = merged[3]

        return ans

import sys
from collections import deque

def solve():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1])
    A = [0] * (n + 1)
    for i in range(1, n + 1):
        A[i] = int(data[1 + i])
    MOD = 998244353

    children = [[] for _ in range(n + 1)]
    indeg = [0] * (n + 1)
    for i in range(1, n + 1):
        a = A[i]
        children[a].append(i)
        indeg[a] += 1

    try:
        import numpy as np
        use_np = True
    except ImportError:
        use_np = False

    peeled = [False] * (n + 1)
    order = []
    q = deque([u for u in range(1, n + 1) if indeg[u] == 0])
    indeg_work = indeg[:]
    while q:
        u = q.popleft()
        peeled[u] = True
        order.append(u)
        p = A[u]
        indeg_work[p] -= 1
        if indeg_work[p] == 0:
            q.append(p)

    on_cycle = [False] * (n + 1)
    for u in range(1, n + 1):
        if not peeled[u]:
            on_cycle[u] = True

    if use_np:
        P = np.empty((n + 1, m), dtype=np.int64)
        ones = np.ones(m, dtype=np.int64)
        for u in order:
            row = ones.copy()
            for c in children[u]:
                row = row * P[c] % MOD
            P[u] = np.cumsum(row) % MOD

        ans = 1
        seen = [False] * (n + 1)
        for u in range(1, n + 1):
            if on_cycle[u] and not seen[u]:
                comp = ones.copy()
                v = u
                while not seen[v]:
                    seen[v] = True
                    for c in children[v]:
                        if not on_cycle[c]:
                            comp = comp * P[c] % MOD
                    v = A[v]
                ans = ans * int(comp.sum() % MOD) % MOD
        print(ans)
    else:
        # Pure-Python fallback
        P = [None] * (n + 1)
        for u in order:
            row = [1] * m
            for c in children[u]:
                pc = P[c]
                row = [(row[k] * pc[k]) % MOD for k in range(m)]
            s = 0
            pref = [0] * m
            for k in range(m):
                s += row[k]
                if s >= MOD:
                    s -= MOD
                pref[k] = s
            P[u] = pref

        ans = 1
        seen = [False] * (n + 1)
        for u in range(1, n + 1):
            if on_cycle[u] and not seen[u]:
                comp = [1] * m
                v = u
                while not seen[v]:
                    seen[v] = True
                    for c in children[v]:
                        if not on_cycle[c]:
                            pc = P[c]
                            comp = [(comp[k] * pc[k]) % MOD for k in range(m)]
                    v = A[v]
                ans = ans * (sum(comp) % MOD) % MOD
        print(ans)

solve()

